package com.bank.risk;

import java.util.logging.*;

public class MinBalanceDemo {
    private static final Logger log = Logger.getLogger(MinBalanceDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Daily balances sorted then rotated: originally 0..70000, rotated
        int[] rotated = {40000, 50000, 60000, 70000, 10000, 20000, 30000};
        // A non-rotated case
        int[] notRotated = {10000, 20000, 30000, 40000};

        BalanceAnalyzer analyzer = new BalanceAnalyzer();

        log.info("Finding minimum balance in rotated cycle");
        log.info("Minimum -> Rs." + analyzer.findMinimum(rotated));

        log.info("Finding minimum balance in non-rotated cycle");
        log.info("Minimum -> Rs." + analyzer.findMinimum(notRotated));
    }
}

// ─── Would be in service/BalanceAnalyzer.java ───
class BalanceAnalyzer {
    // Binary search on the inflection point. O(log n) time, O(1) space.
    int findMinimum(int[] arr) {
        int low = 0, high = arr.length - 1;
        while (low < high) {                    // converge to a single index
            int mid = low + (high - low) / 2;   // overflow-safe
            if (arr[mid] > arr[high]) {
                low = mid + 1;                  // drop is strictly to the right
            } else {
                high = mid;                     // mid could be the minimum
            }
        }
        return arr[low];                        // low == high == min index
    }
}

